AssistantMessageToolRequest(name='create', tool_call_id='toolu_vrtx_0138YQufwe2ySguvcKMjie6V', arguments={'file_text': ':root {
  --bg: #faf8f5;
  --surface: #ffffff;
  --ink: #14130f;
  --ink-2: #4a4844;
  --muted: #8a877f;
  --line: #ebe7df;
  --accent: #1a1a1a;
  --accent-soft: #2b2b2b;
  --tan: #d8c8b0;
  --sage: #b8c2a8;
  --terracotta: #c87a5a;
  --cream: #f1ece2;
  --shadow-sm: 0 1px 2px rgba(20,19,15,.04), 0 2px 8px rgba(20,19,15,.04);
  --shadow-md: 0 6px 24px rgba(20,19,15,.06), 0 2px 6px rgba(20,19,15,.04);
  --radius: 14px;
  --radius-sm: 8px;
  --radius-lg: 22px;
  --serif: "Fraunces", "Cormorant Garamond", Georgia, serif;
  --sans: "Inter", -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
}

* { box-sizing: border-box; }
html, body { margin: 0; padding: 0; }
body {
  font-family: var(--sans);
  background: var(--bg);
  color: var(--ink);
  -webkit-font-smoothing: antialiased;
  line-height: 1.55;
}
img { max-width: 100%; display: block; }
a { color: inherit; text-decoration: none; }
button { font-family: inherit; cursor: pointer; border: 0; background: none; color: inherit; }

h1, h2, h3, h4 {
  font-family: var(--serif);
  font-weight: 500;
  letter-spacing: -0.02em;
  line-height: 1.05;
  margin: 0;
}
h1 { font-size: clamp(2.6rem, 6vw, 5rem); }
h2 { font-size: clamp(1.8rem, 3.2vw, 2.6rem); }
h3 { font-size: 1.25rem; line-height: 1.25; }

.eyebrow {
  display: inline-block;
  font-size: 0.72rem;
  font-weight: 500;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--muted);
  margin-bottom: 14px;
}
.eyebrow.light { color: rgba(255,255,255,.7); }

/* Announcement */
.announcement {
  background: var(--ink);
  color: #f1ece2;
  font-size: 0.78rem;
  letter-spacing: 0.06em;
  overflow: hidden;
}
.announcement-track {
  display: flex;
  gap: 28px;
  padding: 9px 24px;
  justify-content: center;
  white-space: nowrap;
}
.announcement-track span:nth-child(even) { opacity: 0.4; }

/* Header */
.header {
  position: sticky; top: 0; z-index: 50;
  background: rgba(250, 248, 245, 0.85);
  backdrop-filter: saturate(140%) blur(12px);
  -webkit-backdrop-filter: saturate(140%) blur(12px);
  border-bottom: 1px solid var(--line);
}
.header-inner {
  max-width: 1320px;
  margin: 0 auto;
  padding: 16px 32px;
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: center;
  gap: 24px;
}
.nav-left { display: flex; gap: 28px; font-size: 0.92rem; }
.nav-left a { position: relative; padding: 6px 0; transition: color .2s; }
.nav-left a:hover { color: var(--muted); }
.brand {
  font-family: var(--serif);
  font-size: 1.55rem;
  letter-spacing: -0.02em;
  font-weight: 500;
  text-align: center;
}
.brand span { font-style: italic; color: var(--terracotta); }
.header-actions { display: flex; gap: 4px; justify-content: flex-end; align-items: center; }
.menu-btn { display: none; }
.icon-btn {
  position: relative;
  width: 40px; height: 40px;
  border-radius: 999px;
  display: inline-flex; align-items: center; justify-content: center;
  transition: background .2s;
}
.icon-btn:hover { background: var(--cream); }
.cart-count {
  position: absolute;
  top: 4px; right: 4px;
  background: var(--terracotta);
  color: white;
  font-size: 10px;
  font-weight: 600;
  min-width: 16px; height: 16px;
  border-radius: 999px;
  display: inline-flex; align-items: center; justify-content: center;
  padding: 0 4px;
}

/* Hero */
.hero {
  max-width: 1320px;
  margin: 0 auto;
  padding: 64px 32px 80px;
  display: grid;
  grid-template-columns: 1.05fr 1fr;
  gap: 64px;
  align-items: center;
}
.hero-content h1 {
  margin: 6px 0 24px;
}
.hero-content p {
  font-size: 1.08rem;
  color: var(--ink-2);
  max-width: 480px;
  margin: 0 0 36px;
}
.hero-cta { display: flex; gap: 14px; flex-wrap: wrap; align-items: center; }
.btn {
  display: inline-flex; align-items: center; justify-content: center;
  padding: 14px 26px;
  border-radius: 999px;
  font-size: 0.92rem;
  font-weight: 500;
  letter-spacing: 0.01em;
  transition: transform .2s, background .2s, color .2s, box-shadow .2s;
}
.btn-primary { background: var(--ink); color: #f8f5ee; }
.btn-primary:hover { background: var(--accent-soft); transform: translateY(-1px); }
.btn-ghost { color: var(--ink); padding: 14px 16px; }
.btn-ghost:hover { color: var(--terracotta); }
.btn-light { background: #fff; color: var(--ink); }
.btn-light:hover { background: var(--cream); transform: translateY(-1px); }

.hero-meta {
  margin-top: 48px;
  display: flex; gap: 40px;
  padding-top: 28px;
  border-top: 1px solid var(--line);
}
.hero-meta div { display: flex; flex-direction: column; }
.hero-meta strong { font-family: var(--serif); font-size: 1.5rem; font-weight: 500; }
.hero-meta span { font-size: 0.78rem; color: var(--muted); letter-spacing: 0.06em; text-transform: uppercase; }

/* Hero visual collage */
.hero-visual {
  position: relative;
  height: 560px;
}
.hero-card {
  position: absolute;
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-md);
  overflow: hidden;
}
.hero-card-1 {
  width: 60%; height: 75%;
  top: 0; right: 0;
  background: linear-gradient(135deg, #d8c8b0 0%, #b69b78 100%);
}
.hero-card-1::after {
  content: ""; position: absolute; inset: 0;
  background:
    radial-gradient(circle at 70% 30%, rgba(255,255,255,.4), transparent 40%),
    radial-gradient(circle at 30% 80%, rgba(0,0,0,.15), transparent 50%);
}
.hero-card-2 {
  width: 45%; height: 50%;
  bottom: 0; left: 0;
  background: linear-gradient(160deg, #2c3a2a 0%, #4a5d44 100%);
}
.hero-card-2::after {
  content: ""; position: absolute; inset: 0;
  background: radial-gradient(circle at 50% 40%, rgba(184,194,168,.35), transparent 60%);
}
.hero-card-3 {
  width: 35%; height: 35%;
  top: 38%; left: 18%;
  background: linear-gradient(140deg, #e8d9c0 0%, #c87a5a 100%);
  z-index: 2;
}
.hero-card-3::after {
  content: ""; position: absolute; inset: 0;
  background: radial-gradient(ellipse at 30% 30%, rgba(255,255,255,.45), transparent 55%);
}
.hero-badge {
  position: absolute;
  bottom: 30px; right: 24px;
  background: #fff;
  padding: 14px 18px;
  border-radius: var(--radius);
  box-shadow: var(--shadow-md);
  z-index: 3;
  max-width: 200px;
}
.hero-badge span {
  display: inline-block;
  font-size: 0.65rem;
  font-weight: 600;
  letter-spacing: 0.18em;
  color: var(--terracotta);
  margin-bottom: 4px;
}
.hero-badge p {
  margin: 0;
  font-family: var(--serif);
  font-size: 0.95rem;
  line-height: 1.3;
}

/* Section heads */
.section, .categories, .deals, .editorial {
  max-width: 1320px;
  margin: 0 auto;
  padding: 80px 32px;
}
.section-head {
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  gap: 24px;
  margin-bottom: 40px;
  flex-wrap: wrap;
}
.link-arrow {
  font-size: 0.9rem;
  color: var(--ink-2);
  border-bottom: 1px solid currentColor;
  padding-bottom: 2px;
  transition: color .2s;
}
.link-arrow:hover { color: var(--terracotta); }

/* Filter tabs */
.filter-tabs { display: flex; gap: 6px; flex-wrap: wrap; }
.filter-tabs button {
  padding: 8px 16px;
  border-radius: 999px;
  font-size: 0.85rem;
  color: var(--ink-2);
  border: 1px solid var(--line);
  transition: all .2s;
}
.filter-tabs button:hover { border-color: var(--ink); }
.filter-tabs button.active {
  background: var(--ink);
  color: #f8f5ee;
  border-color: var(--ink);
}

/* Categories */
.cat-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 16px;
}
.cat-card {
  position: relative;
  aspect-ratio: 4 / 5;
  border-radius: var(--radius);
  overflow: hidden;
  cursor: pointer;
  transition: transform .35s ease;
}
.cat-card:hover { transform: translateY(-4px); }
.cat-card .cat-bg {
  position: absolute; inset: 0;
}
.cat-card::after {
  content: "";
  position: absolute; inset: 0;
  background: linear-gradient(180deg, transparent 50%, rgba(0,0,0,.55) 100%);
}
.cat-card .cat-label {
  position: absolute;
  bottom: 16px; left: 18px; right: 18px;
  z-index: 2;
  color: #fff;
}
.cat-card .cat-label h3 {
  font-size: 1.15rem;
  margin-bottom: 2px;
}
.cat-card .cat-label span {
  font-size: 0.78rem;
  opacity: 0.8;
}

/* Product grid */
.product-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 28px 24px;
}
.product {
  display: flex; flex-direction: column;
  cursor: pointer;
}
.product-image {
  position: relative;
  aspect-ratio: 1 / 1.15;
  border-radius: var(--radius);
  overflow: hidden;
  margin-bottom: 14px;
  background: var(--cream);
  transition: transform .35s ease;
}
.product:hover .product-image { transform: translateY(-3px); }
.product-image .ph {
  position: absolute; inset: 0;
}
.product-image .ph::after {
  content: "";
  position: absolute; inset: 0;
  background:
    radial-gradient(ellipse at 60% 40%, rgba(255,255,255,.4), transparent 60%),
    radial-gradient(ellipse at 30% 80%, rgba(0,0,0,.15), transparent 60%);
}
.tag-pill {
  position: absolute; top: 12px; left: 12px;
  background: #fff;
  padding: 5px 10px;
  border-radius: 999px;
  font-size: 0.68rem;
  font-weight: 600;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  z-index: 2;
}
.tag-pill.new { color: var(--terracotta); }
.tag-pill.sale { color: #b04a2a; }
.wishlist-btn {
  position: absolute; top: 10px; right: 10px;
  width: 36px; height: 36px;
  border-radius: 999px;
  background: rgba(255,255,255,.9);
  display: inline-flex; align-items: center; justify-content: center;
  z-index: 2;
  transition: background .2s, transform .2s;
}
.wishlist-btn:hover { background: #fff; transform: scale(1.05); }
.wishlist-btn.active svg { fill: var(--terracotta); stroke: var(--terracotta); }
.add-btn {
  position: absolute;
  left: 12px; right: 12px; bottom: 12px;
  background: var(--ink);
  color: #f8f5ee;
  padding: 11px;
  border-radius: 999px;
  font-size: 0.82rem;
  font-weight: 500;
  opacity: 0;
  transform: translateY(8px);
  transition: opacity .25s, transform .25s, background .2s;
  z-index: 2;
}
.product:hover .add-btn { opacity: 1; transform: translateY(0); }
.add-btn:hover { background: var(--accent-soft); }

.product-info {
  display: flex; justify-content: space-between; gap: 12px;
  align-items: flex-start;
}
.product-info h4 {
  font-family: var(--sans);
  font-size: 0.95rem;
  font-weight: 500;
  margin: 0 0 2px;
}
.product-info .product-meta {
  font-size: 0.82rem;
  color: var(--muted);
}
.product-price {
  text-align: right;
  font-size: 0.95rem;
  font-weight: 500;
  white-space: nowrap;
}
.product-price .strike {
  display: block;
  font-size: 0.78rem;
  color: var(--muted);
  text-decoration: line-through;
  font-weight: 400;
}

/* Deals */
.deals {
  padding-top: 40px;
}
.deals-banner {
  background: linear-gradient(135deg, #2a2d28 0%, #1a1c18 100%);
  color: #f1ece2;
  border-radius: var(--radius-lg);
  padding: 64px 56px;
  display: grid;
  grid-template-columns: 1.1fr 1fr;
  gap: 48px;
  align-items: center;
  position: relative;
  overflow: hidden;
  margin-bottom: 56px;
}
.deals-banner h2 { font-size: clamp(2rem, 4vw, 3.4rem); margin: 8px 0 18px; }
.deals-banner p { color: rgba(241,236,226,.75); max-width: 420px; margin: 0 0 28px; }
.deals-banner .btn { margin-top: 4px; }
.countdown {
  display: flex;
  gap: 12px;
  margin: 0 0 32px;
}
.countdown .unit {
  background: rgba(255,255,255,0.08);
  border: 1px solid rgba(255,255,255,0.12);
  padding: 14px 18px;
  border-radius: var(--radius-sm);
  text-align: center;
  min-width: 72px;
}
.countdown .num {
  font-family: var(--serif);
  font-size: 1.6rem;
  display: block;
  line-height: 1;
}
.countdown .lbl {
  display: block;
  font-size: 0.68rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: rgba(241,236,226,.55);
  margin-top: 6px;
}
.deals-visual {
  position: relative;
  height: 320px;
  border-radius: var(--radius);
  background:
    radial-gradient(circle at 70% 30%, rgba(216,200,176,.5), transparent 50%),
    radial-gradient(circle at 30% 70%, rgba(200,122,90,.45), transparent 55%),
    linear-gradient(135deg, #3d3a32, #2a2826);
  overflow: hidden;
}
.deals-visual::before {
  content: "−40%";
  position: absolute;
  top: 50%; left: 50%;
  transform: translate(-50%, -50%);
  font-family: var(--serif);
  font-size: 7rem;
  font-style: italic;
  color: rgba(255,255,255,0.95);
}

.deal-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}
.deal-card {
  background: var(--surface);
  border-radius: var(--radius);
  padding: 24px;
  display: flex; gap: 18px; align-items: center;
  border: 1px solid var(--line);
  transition: border-color .2s, transform .2s;
  cursor: pointer;
}
.deal-card:hover { border-color: var(--ink); transform: translateY(-2px); }
.deal-thumb {
  width: 96px; height: 96px;
  border-radius: var(--radius-sm);
  flex-shrink: 0;
  position: relative;
  overflow: hidden;
}
.deal-thumb::after {
  content: "";
  position: absolute; inset: 0;
  background: radial-gradient(circle at 60% 40%, rgba(255,255,255,.35), transparent 65%);
}
.deal-info h4 { font-family: var(--sans); font-size: 0.95rem; font-weight: 500; margin: 0 0 4px; }
.deal-info .meta { font-size: 0.78rem; color: var(--muted); margin-bottom: 6px; }
.deal-info .price { font-weight: 500; }
.deal-info .price .strike { color: var(--muted); text-decoration: line-through; font-weight: 400; margin-left: 6px; font-size: 0.85rem; }
.deal-info .save { display: inline-block; margin-left: 8px; color: var(--terracotta); font-size: 0.8rem; font-weight: 600; }

/* Editorial */
.editorial { padding-top: 40px; }
.edit-grid {
  display: grid;
  grid-template-columns: 1.4fr 1fr 1fr;
  gap: 24px;
}
.edit-card {
  background: var(--surface);
  border-radius: var(--radius);
  overflow: hidden;
  border: 1px solid var(--line);
  display: flex; flex-direction: column;
  transition: transform .25s, border-color .2s;
  cursor: pointer;
}
.edit-card:hover { transform: translateY(-4px); border-color: var(--ink); }
.edit-feature { grid-row: span 2; }
.edit-image {
  aspect-ratio: 4 / 3;
  position: relative;
  overflow: hidden;
}
.edit-feature .edit-image { aspect-ratio: 5 / 6; }
.edit-img-1 {
  background:
    radial-gradient(circle at 30% 30%, rgba(255,255,255,.3), transparent 40%),
    linear-gradient(160deg, #c2a589 0%, #6b5742 100%);
}
.edit-img-2 {
  background:
    radial-gradient(circle at 70% 30%, rgba(255,255,255,.35), transparent 50%),
    linear-gradient(150deg, #b8c2a8 0%, #5a6b4f 100%);
}
.edit-img-3 {
  background:
    radial-gradient(circle at 40% 50%, rgba(255,255,255,.3), transparent 45%),
    linear-gradient(140deg, #e8d9c0 0%, #c87a5a 100%);
}
.edit-body { padding: 22px 24px 26px; flex: 1; display: flex; flex-direction: column; }
.edit-feature .edit-body { padding: 32px; }
.edit-body .tag {
  font-size: 0.7rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--terracotta);
  font-weight: 600;
  margin-bottom: 10px;
}
.edit-body h3 {
  font-size: 1.3rem;
  margin-bottom: 10px;
}
.edit-feature .edit-body h3 { font-size: 1.8rem; }
.edit-body p {
  margin: 0 0 16px;
  color: var(--ink-2);
  font-size: 0.95rem;
}
.edit-meta {
  margin-top: auto;
  display: flex; gap: 8px;
  font-size: 0.8rem;
  color: var(--muted);
}

/* Values */
.values {
  max-width: 1320px;
  margin: 0 auto;
  padding: 24px 32px 80px;
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
}
.value {
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  padding: 28px;
  text-align: left;
}
.value-icon {
  font-size: 1.6rem;
  margin-bottom: 14px;
  color: var(--terracotta);
}
.value h4 {
  font-family: var(--sans);
  font-size: 1rem;
  font-weight: 600;
  margin: 0 0 6px;
}
.value p {
  margin: 0;
  font-size: 0.88rem;
  color: var(--muted);
  line-height: 1.5;
}

/* Newsletter */
.newsletter {
  background: var(--cream);
  margin: 0 32px;
  border-radius: var(--radius-lg);
  max-width: 1256px;
  margin-left: auto; margin-right: auto;
}
.newsletter-inner {
  padding: 80px 40px;
  text-align: center;
  max-width: 620px;
  margin: 0 auto;
}
.newsletter h2 { font-size: clamp(1.8rem, 3vw, 2.6rem); margin-bottom: 12px; }
.newsletter p { color: var(--ink-2); margin: 0 0 28px; }
.newsletter-form {
  display: flex;
  gap: 8px;
  background: #fff;
  padding: 6px;
  border-radius: 999px;
  border: 1px solid var(--line);
  max-width: 460px;
  margin: 0 auto;
}
.newsletter-form input {
  flex: 1;
  border: 0;
  background: transparent;
  padding: 12px 18px;
  font: inherit;
  outline: none;
  color: var(--ink);
}
.newsletter-form .btn { padding: 12px 22px; }
.form-msg {
  margin-top: 14px;
  font-size: 0.85rem;
  color: var(--terracotta);
  min-height: 20px;
}

/* Footer */
.footer {
  margin-top: 80px;
  padding: 64px 32px 28px;
  max-width: 1320px;
  margin-left: auto; margin-right: auto;
  border-top: 1px solid var(--line);
}
.footer-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr;
  gap: 48px;
  margin-bottom: 48px;
}
.footer-brand .brand { display: inline-block; margin-bottom: 14px; }
.footer-brand p { color: var(--ink-2); max-width: 320px; font-size: 0.92rem; }
.footer h5 {
  font-family: var(--sans);
  font-size: 0.78rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--muted);
  margin: 0 0 16px;
  font-weight: 600;
}
.footer ul { list-style: none; padding: 0; margin: 0; display: grid; gap: 10px; }
.footer ul a { color: var(--ink); font-size: 0.92rem; transition: color .2s; }
.footer ul a:hover { color: var(--terracotta); }
.footer-bottom {
  display: flex;
  justify-content: space-between;
  padding-top: 24px;
  border-top: 1px solid var(--line);
  font-size: 0.82rem;
  color: var(--muted);
}
.legal { display: flex; gap: 18px; }

/* Toast */
.toast {
  position: fixed;
  bottom: 24px; left: 50%;
  transform: translateX(-50%) translateY(20px);
  background: var(--ink);
  color: #f8f5ee;
  padding: 12px 20px;
  border-radius: 999px;
  font-size: 0.9rem;
  box-shadow: var(--shadow-md);
  opacity: 0;
  pointer-events: none;
  transition: opacity .25s, transform .25s;
  z-index: 100;
}
.toast.show { opacity: 1; transform: translateX(-50%) translateY(0); }

/* Responsive */
@media (max-width: 1024px) {
  .nav-left { display: none; }
  .menu-btn { display: inline-flex; }
  .header-inner { grid-template-columns: auto 1fr auto; }
  .brand { text-align: left; }
  .hero { grid-template-columns: 1fr; padding: 48px 24px 64px; gap: 40px; }
  .hero-visual { height: 420px; }
  .cat-grid { grid-template-columns: repeat(3, 1fr); }
  .product-grid { grid-template-columns: repeat(3, 1fr); }
  .deals-banner { grid-template-columns: 1fr; padding: 48px 32px; }
  .deals-visual { height: 200px; }
  .deal-grid { grid-template-columns: repeat(2, 1fr); }
  .edit-grid { grid-template-columns: 1fr 1fr; }
  .edit-feature { grid-column: span 2; grid-row: auto; }
  .edit-feature .edit-image { aspect-ratio: 16/9; }
  .values { grid-template-columns: repeat(2, 1fr); }
  .footer-grid { grid-template-columns: 1fr 1fr; }
}
@media (max-width: 640px) {
  .section, .categories, .deals, .editorial { padding: 56px 20px; }
  .header-inner { padding: 14px 20px; }
  .announcement-track { font-size: 0.7rem; padding: 8px 16px; }
  .announcement-track span:nth-child(n+5) { display: none; }
  .hero { padding: 32px 20px 56px; }
  .hero-meta { gap: 24px; flex-wrap: wrap; }
  .cat-grid { grid-template-columns: repeat(2, 1fr); gap: 12px; }
  .product-grid { grid-template-columns: repeat(2, 1fr); gap: 24px 14px; }
  .deal-grid { grid-template-columns: 1fr; }
  .edit-grid { grid-template-columns: 1fr; }
  .edit-feature { grid-column: auto; }
  .values { grid-template-columns: 1fr 1fr; }
  .footer-grid { grid-template-columns: 1fr; gap: 32px; }
  .footer-bottom { flex-direction: column; gap: 12px; }
  .countdown .unit { padding: 10px 12px; min-width: 60px; }
  .add-btn { opacity: 1; transform: none; }
  .newsletter-form { flex-direction: column; border-radius: var(--radius); }
  .newsletter-form .btn { border-radius: 999px; }
}
