// ----- Data -----
const categories = [
  { name: "Living",   count: "82 items",  grad: "linear-gradient(160deg,#d8c8b0,#9b8367)" },
  { name: "Kitchen",  count: "64 items",  grad: "linear-gradient(160deg,#e8d9c0,#c87a5a)" },
  { name: "Bedding",  count: "38 items",  grad: "linear-gradient(160deg,#cdd5be,#6b7a5c)" },
  { name: "Apparel",  count: "47 items",  grad: "linear-gradient(160deg,#3a3a36,#1a1a18)" },
  { name: "Objects",  count: "29 items",  grad: "linear-gradient(160deg,#e6cfb8,#8a6a4e)" }
];

const products = [
  { id: 1, name: "Linen throw blanket", maker: "Made in Portugal", price: 148, cat: "home",    tag: "new",  grad: "linear-gradient(150deg,#d8c8b0,#a88c6a)" },
  { id: 2, name: "Stoneware mug, set of 2", maker: "Hand-thrown",  price: 42, cat: "kitchen", tag: null,   grad: "linear-gradient(150deg,#efe6d6,#b8a886)" },
  { id: 3, name: "Merino crewneck",       maker: "Knit in Italy",  price: 195, was: 245, cat: "apparel", tag: "sale", grad: "linear-gradient(150deg,#3a3a36,#1f1f1c)" },
  { id: 4, name: "Brass table lamp",      maker: "Solid brass",    price: 320, cat: "objects", tag: null,  grad: "linear-gradient(150deg,#e3c79a,#8a6534)" },
  { id: 5, name: "Oak cutting board",     maker: "French oak",     price: 78,  cat: "kitchen", tag: "new", grad: "linear-gradient(150deg,#dbb98a,#7a5630)" },
  { id: 6, name: "Wool throw, sage",      maker: "Woven in Wales", price: 168, cat: "home",    tag: null,  grad: "linear-gradient(150deg,#b8c2a8,#5e6e54)" },
  { id: 7, name: "Linen pajama set",      maker: "Garment dyed",   price: 188, cat: "apparel", tag: null,  grad: "linear-gradient(150deg,#e0d4be,#8a7a5e)" },
  { id: 8, name: "Ceramic vase, terracotta", maker: "One of a kind", price: 96, cat: "objects", tag: "new", grad: "linear-gradient(150deg,#e6a484,#a8553a)" }
];

const deals = [
  { name: "Cashmere scarf",  meta: "Dune", price: 138, was: 220, grad: "linear-gradient(140deg,#e6d6bc,#a88c6a)" },
  { name: "Glass carafe",    meta: "1L",   price: 38,  was: 64,  grad: "linear-gradient(140deg,#cfdce0,#6c8189)" },
  { name: "Linen apron",     meta: "Olive", price: 48, was: 78,  grad: "linear-gradient(140deg,#b8c2a8,#5e6e54)" }
];

// ----- Render -----
const catGrid = document.getElementById("catGrid");
catGrid.innerHTML = categories.map(c => `
  <div class="cat-card" tabindex="0">
    <div class="cat-bg" style="background:${c.grad}"></div>
    <div class="cat-label">
      <h3>${c.name}</h3>
      <span>${c.count}</span>
    </div>
  </div>
`).join("");

const productGrid = document.getElementById("productGrid");
function renderProducts(filter = "all") {
  const list = filter === "all" ? products : products.filter(p => p.cat === filter);
  productGrid.innerHTML = list.map(p => `
    <article class="product" data-id="${p.id}">
      <div class="product-image">
        <div class="ph" style="background:${p.grad}"></div>
        ${p.tag ? `<span class="tag-pill ${p.tag}">${p.tag === "sale" ? "Sale" : "New"}</span>` : ""}
        <button class="wishlist-btn" aria-label="Save to wishlist">
          <svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="1.6"><path d="M12 21s-7-4.35-9.5-9A5.5 5.5 0 0 1 12 6a5.5 5.5 0 0 1 9.5 6c-2.5 4.65-9.5 9-9.5 9Z"/></svg>
        </button>
        <button class="add-btn" data-add="${p.id}">Add to bag — $${p.price}</button>
      </div>
      <div class="product-info">
        <div>
          <h4>${p.name}</h4>
          <div class="product-meta">${p.maker}</div>
        </div>
        <div class="product-price">
          $${p.price}
          ${p.was ? `<span class="strike">$${p.was}</span>` : ""}
        </div>
      </div>
    </article>
  `).join("");
}
renderProducts();

const dealGrid = document.getElementById("dealGrid");
dealGrid.innerHTML = deals.map(d => `
  <div class="deal-card">
    <div class="deal-thumb" style="background:${d.grad}"></div>
    <div class="deal-info">
      <h4>${d.name}</h4>
      <div class="meta">${d.meta}</div>
      <div class="price">$${d.price}<span class="strike">$${d.was}</span><span class="save">−${Math.round((1 - d.price/d.was)*100)}%</span></div>
    </div>
  </div>
`).join("");

// ----- Filters -----
document.getElementById("filterTabs").addEventListener("click", (e) => {
  const btn = e.target.closest("button[data-filter]");
  if (!btn) return;
  document.querySelectorAll("#filterTabs button").forEach(b => b.classList.remove("active"));
  btn.classList.add("active");
  renderProducts(btn.dataset.filter);
});

// ----- Wishlist + add to cart -----
let cart = 0;
const cartCount = document.getElementById("cartCount");
const cartBtn = document.getElementById("cartBtn");

productGrid.addEventListener("click", (e) => {
  const wish = e.target.closest(".wishlist-btn");
  if (wish) {
    e.stopPropagation();
    wish.classList.toggle("active");
    showToast(wish.classList.contains("active") ? "Saved to wishlist" : "Removed from wishlist");
    return;
  }
  const add = e.target.closest("[data-add]");
  if (add) {
    e.stopPropagation();
    cart += 1;
    cartCount.textContent = cart;
    cartBtn.animate(
      [{ transform: "scale(1)" }, { transform: "scale(1.15)" }, { transform: "scale(1)" }],
      { duration: 350, easing: "ease-out" }
    );
    showToast("Added to bag");
  }
});

dealGrid.addEventListener("click", () => {
  cart += 1; cartCount.textContent = cart; showToast("Added to bag");
});

// ----- Toast -----
const toast = document.getElementById("toast");
let toastTimer;
function showToast(msg) {
  toast.textContent = msg;
  toast.classList.add("show");
  clearTimeout(toastTimer);
  toastTimer = setTimeout(() => toast.classList.remove("show"), 2000);
}

// ----- Newsletter -----
const form = document.getElementById("newsletterForm");
const formMsg = document.getElementById("formMsg");
form.addEventListener("submit", (e) => {
  e.preventDefault();
  const email = form.querySelector("input").value.trim();
  if (!email) return;
  formMsg.textContent = "Welcome aboard. Check your inbox for a confirmation.";
  formMsg.style.color = "var(--ink-2)";
  form.reset();
});

// ----- Countdown -----
const countdownEl = document.getElementById("countdown");
const target = new Date();
target.setDate(target.getDate() + 3);
target.setHours(23, 59, 59, 0);

function tick() {
  const diff = Math.max(0, target - new Date());
  const d = Math.floor(diff / 86400000);
  const h = Math.floor((diff % 86400000) / 3600000);
  const m = Math.floor((diff % 3600000) / 60000);
  const s = Math.floor((diff % 60000) / 1000);
  countdownEl.innerHTML = [
    ["Days", d], ["Hours", h], ["Mins", m], ["Secs", s]
  ].map(([l, v]) => `<div class="unit"><span class="num">${String(v).padStart(2,"0")}</span><span class="lbl">${l}</span></div>`).join("");
}
tick();
setInterval(tick, 1000);

